import json,re,pathlib
root=pathlib.Path(__file__).resolve().parents[2]
a=json.loads((root/'lib/l10n/app_ko.arb').read_text())
steps=[]
def add(title, keys, image='haven_captain', label='태양계'):
 steps.append(dict(title=title,label=label,paragraphs=[a[k] for k in keys],image=image))
for i,(title,img) in enumerate([('증가하는 반물질 입자','haven_conference'),('위상 정박기 시험','haven_defense'),('원정대 출항','haven_captain'),('알 수 없는 추적자','haven_severance')]):add(title,[f'n_open{i}'],img,'오프닝')
add('첫 식민지',['n_mars0','n_mars1','n_mars2'],'story_colony')
add('첫 송신',['n_transmission0','n_transmission1'],'story_transmission')
add('태양계 밖으로',['n_warp0','n_warp1'],'story_warp')
titles=dict(re.findall(r'(\d+)\{([^{}]*)\}',a['c_title']))
bodies=dict(re.findall(r'(\d+)\{([^{}]*)\}',a['c_body']))
for s,t in titles.items():steps.append(dict(title=t,label=f'구역 {s} · '+('최종 작전 브리핑' if s=='26' else '작전 완료 장면'),paragraphs=[bodies[s]],image=f'story_sector_{int(s):02}'))
add(a['c_finalTitle'],['c_stabilize','c_syncReady','c_syncProgress','c_guardian','c_counterattack'],'story_counterattack','최종 임무 · 진행 목표')
steps[-1]['paragraphs'][2]=a['c_syncProgress'].replace('{percent}','100')
add(a['c_endingTitle'],['c_endingBody'],'story_ending','엔딩')
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>헤이븐 · 단계별 스토리</title><style>
*{box-sizing:border-box}body{margin:0;background:#080d18;color:#ecf2fc;font-family:system-ui,-apple-system,sans-serif}header{height:58px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #243144}header b{font-size:16px}header span{font-size:12px;color:#97a8c0}.layout{display:grid;grid-template-columns:250px 1fr;height:calc(100dvh - 58px)}nav{overflow:auto;border-right:1px solid #243144;padding:12px}nav button{display:block;width:100%;text-align:left;background:none;color:#aab8ce;border:0;border-radius:7px;padding:11px 12px;cursor:pointer;font:inherit;font-size:13px}nav button.active{background:#1c314b;color:#b6e8ff}nav small{display:block;font-size:10px;opacity:.7;margin-bottom:4px}main{min-width:0;display:flex;flex-direction:column;padding:28px;overflow:auto}.scene{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);flex:1;gap:32px;align-items:center}.art{width:100%;aspect-ratio:16/9;object-fit:contain;border-radius:12px}.label{color:#7ecbea;font-size:12px;letter-spacing:.08em}h1{font-size:clamp(23px,2.4vw,36px);line-height:1.3;margin:12px 0 24px}p{font-size:clamp(16px,1.45vw,21px);line-height:1.8;word-break:keep-all;white-space:pre-line;color:#ced9eb;margin:0 0 18px}footer{display:flex;align-items:center;justify-content:space-between;margin-top:24px;gap:12px}footer button{background:#233e59;color:white;border:1px solid #365b7c;border-radius:7px;padding:11px 22px;cursor:pointer}button:disabled{opacity:.3;cursor:default}#count{font-size:13px;color:#91a4bd}@media(max-width:900px){.layout{grid-template-columns:180px 1fr}main{padding:18px}.scene{gap:18px}.art{aspect-ratio:16/9}p{font-size:16px}h1{font-size:23px}header{padding:0 14px}}@media(max-width:600px){header span{display:none}.layout{display:flex;flex-direction:column;height:auto}nav{display:flex;overflow:auto;flex-shrink:0;padding:8px;border-right:0;border-bottom:1px solid #243144}nav button{min-width:145px}main{min-height:calc(100dvh - 145px)}.scene{display:flex;flex-direction:column;align-items:stretch}.art{aspect-ratio:16/9;max-height:220px}.copy{padding-top:6px}}
</style><header><b>헤이븐 · 단계별 스토리</b><span>현재 게임 대사 · 스토리 열람용</span></header><div class="layout"><nav aria-label="스토리 단계"></nav><main><div class="scene"><img class="art" alt=""><div class="copy"><div class="label"></div><h1></h1><div id="body"></div></div></div><footer><button id="prev">이전</button><span id="count"></span><button id="next">다음</button></footer></main></div><script>
const steps=DATA;let index=0;const nav=document.querySelector('nav');steps.forEach((s,i)=>{const b=document.createElement('button');const small=document.createElement('small');small.textContent=String(i+1).padStart(2,'0')+' · '+s.label;b.append(small,document.createTextNode(s.title));b.onclick=()=>show(i);nav.append(b)});function show(i){index=Math.max(0,Math.min(steps.length-1,i));const s=steps[index];document.querySelector('.label').textContent=s.label;document.querySelector('h1').textContent=s.title;document.querySelector('.art').src='/assets/assets/cinematics/'+s.image+(s.image.startsWith('story_')?'.webp':'.png');document.querySelector('.art').alt=s.title;document.querySelector('#body').replaceChildren(...s.paragraphs.map(t=>{const p=document.createElement('p');p.textContent=t;return p}));[...nav.children].forEach((b,j)=>{b.classList.toggle('active',j===index);b.setAttribute('aria-current',j===index?'step':'false')});document.querySelector('#count').textContent=(index+1)+' / '+steps.length;document.querySelector('#prev').disabled=index===0;document.querySelector('#next').disabled=index===steps.length-1;history.replaceState(null,'','#'+(index+1))}document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(index+1);if(e.key==='ArrowLeft')show(index-1)});show(Number(location.hash.slice(1)||1)-1);
</script></html>'''.replace('DATA',json.dumps(steps,ensure_ascii=False).replace('</','<\\/'))
(root/'build/game-recording-web/story.html').write_text(html)
print(f'{len(steps)} stages written')
